<script setup lang="ts">
import { onMounted, ref, watch } from 'vue';
import { BookOpen, CalendarDays, ExternalLink, FolderOpen, GraduationCap, MapPin, Video } from 'lucide-vue-next';
import StudentPractice from './StudentPractice.vue';
import StudentBookings from './StudentBookings.vue';
const props=defineProps<{workspace:{id:string;name:string}}>();
type Lesson={id:string;title:string;startsAt:string;mode:'ONLINE'|'ONSITE'|'HYBRID';meetingUrl:string|null;location:string|null};
type Enrollment={id:string;course:{id:string;title:string;summary:string|null;subject:{name:string}|null;resources:{id:string;title:string;source:string;url:string|null}[];sessions:Lesson[]}};
type PublishedNotes={id:string;notes:string;approvedAt:string|null;session:{id:string;courseId:string|null;title:string}};
const lessonNotes=ref<PublishedNotes[]>([]);
const courses=ref<Enrollment[]>([]),loading=ref(true),error=ref('');
async function load(){loading.value=true;error.value='';try{const r=await fetch(`/api/v1/workspaces/${props.workspace.id}/classroom`,{credentials:'same-origin'});if(!r.ok)throw Error(r.status===403?'No tienes permiso para este curso.':'No se pudieron cargar tus cursos.');courses.value=await r.json() as Enrollment[];const notesResponse=await fetch(`/api/v1/workspaces/${props.workspace.id}/class-alive/published`,{credentials:'same-origin'});if(notesResponse.ok)lessonNotes.value=await notesResponse.json() as PublishedNotes[];else lessonNotes.value=[];}catch(e){error.value=e instanceof Error?e.message:'Hubo un problema';}finally{loading.value=false;}}
onMounted(load);watch(()=>props.workspace.id,load);
</script>
<template>
<main class="mx-auto max-w-5xl p-6 md:p-10"><div class="mb-8"><span class="text-xs font-extrabold tracking-widest text-brand">AULA DIGITAL</span><h1 class="mt-3 text-3xl font-extrabold">Mis clases en {{ workspace.name }}</h1><p class="mt-3 text-sm text-muted">Tu agenda, tus materiales y tus cursos en un mismo lugar.</p></div>
<p v-if="loading" class="rounded-xl bg-white p-6 text-sm text-muted">Cargando tus clases...</p><p v-else-if="error" role="alert" class="rounded-xl bg-rose-50 p-6 text-sm text-rose-700">{{ error }}</p>
<div v-else-if="!courses.length" class="rounded-3xl border border-outline bg-white p-10 text-center"><GraduationCap :size="35" class="mx-auto text-brand"/><h2 class="mt-5 text-lg font-extrabold">Tu espacio ya está listo</h2><p class="mx-auto mt-3 max-w-sm text-sm leading-6 text-muted">Cuando el administrador te inscriba en un curso, encontrarás aquí tus clases y materiales.</p></div>
<div v-else class="space-y-5"><section v-for="enrollment in courses" :key="enrollment.id" class="rounded-2xl border border-outline bg-white p-6"><div class="flex items-center gap-3"><div class="grid size-11 place-items-center rounded-xl bg-violet-100 text-brand"><BookOpen :size="24"/></div><div><p class="text-xs font-bold text-brand">{{ enrollment.course.subject?.name || 'Curso' }}</p><h2 class="mt-1 text-lg font-extrabold">{{ enrollment.course.title }}</h2></div></div><p v-if="enrollment.course.summary" class="mt-4 text-sm text-muted">{{ enrollment.course.summary }}</p>
<div v-if="lessonNotes.some(n=>n.session.courseId===enrollment.course.id)" class="mt-5 rounded-xl bg-violet-50 p-4"><h3 class="text-sm font-extrabold text-brand">Clase Viva · resumen del profesor</h3><div v-for="note in lessonNotes.filter(n=>n.session.courseId===enrollment.course.id)" :key="note.id" class="mt-3 border-t border-violet-200 pt-3"><p class="text-xs font-bold">{{ note.session.title }}</p><p class="mt-1 whitespace-pre-wrap text-sm leading-6">{{ note.notes }}</p></div></div>
<div class="mt-7 grid gap-5 md:grid-cols-2"><div><h3 class="flex items-center gap-2 text-sm font-extrabold"><CalendarDays :size="17"/> Sesiones</h3><div v-for="session in enrollment.course.sessions" :key="session.id" class="mt-3 rounded-xl bg-slate-50 p-4"><p class="text-sm font-semibold">{{ session.title }}</p><p class="mt-1 text-xs text-muted">{{ new Date(session.startsAt).toLocaleString('es-CO') }}</p><p v-if="session.location" class="mt-2 flex items-center gap-1 text-xs text-slate-600"><MapPin :size="13"/>{{ session.location }}</p><a v-if="session.meetingUrl" :href="session.meetingUrl" target="_blank" rel="noopener noreferrer" class="mt-3 inline-flex items-center gap-2 rounded-lg bg-brand px-3 py-2 text-xs font-bold text-white"><Video :size="14"/> Entrar a la clase <ExternalLink :size="13"/></a></div><p v-if="!enrollment.course.sessions.length" class="mt-3 text-xs text-muted">Todavía no hay sesiones agendadas.</p></div><div><h3 class="flex items-center gap-2 text-sm font-extrabold"><FolderOpen :size="17"/> Materiales</h3><div v-for="resource in enrollment.course.resources" :key="resource.id" class="mt-3 rounded-xl border border-outline p-4"><p class="text-sm font-medium">{{ resource.title }}</p><a v-if="resource.url" :href="resource.url" target="_blank" rel="noopener noreferrer" class="mt-2 inline-flex items-center gap-1 text-xs font-bold text-brand">Abrir recurso <ExternalLink :size="13"/></a></div><p v-if="!enrollment.course.resources.length" class="mt-3 text-xs text-muted">Aún no hay materiales publicados.</p></div></div></section></div>
<div v-if="!loading && !error" class="mt-8"><StudentBookings :workspace-id="workspace.id" :sessions="courses.flatMap(enrollment=>enrollment.course.sessions)" />
<StudentPractice :workspace-id="workspace.id" /></div>
</main>
</template>
